import java.util.Arrays;

public class Solution {
    public int[] nextPermutation(int[] nums) {
        int n = nums.length;
        int k = -1;
        for (int i = n - 1; i > 0; i--) {
            if (nums[i - 1] < nums[i]) {
                k = i - 1;
                break;
            }
        }
        if (k == -1) {
            reverse(nums, 0, n - 1);
        } else {
            int l = 0;
            for (int i = n - 1; i > k; i--) {
                if (nums[i] > nums[k]) {
                    l = i;
                    break;
                }
            }
            swap(nums, k, l);
            reverse(nums, k + 1, n - 1);
        }
        return nums;
    }

    private void reverse(int[] nums, int start, int end) {
        while (start < end) {
            swap(nums, start, end);
            start++;
            end--;
        }
    }

    private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
}
```


