#include <vector>
#include <string>

int minCut(std::string s) {
    int n = s.size();
    std::vector<int> dp(n + 1, 0);
    std::vector<std::vector<bool>> isPalindrome(n, std::vector<bool>(n, false));

    for (int i = 0; i <= n; i++) {
        dp[i] = i - 1;
    }

    for (int j = 1; j < n; j++) {
        for (int i = j; i >= 0; i--) {
            if (s[i] == s[j] && (j - i < 2 || isPalindrome[i + 1][j - 1])) {
                isPalindrome[i][j] = true;
                dp[j + 1] = std::min(dp[j + 1], dp[i] + 1);
            }
        }
    }

    return dp[n];
}
